create or replace function ops.scac_mutation_registration_v101(p_expected_digest text,p_ingress_key text)
returns jsonb language plpgsql stable security definer set search_path=pg_catalog,ops,pg_temp as $fn$
declare v ops.scac_mutation_registry_version%rowtype; e ops.scac_mutation_registry_entry%rowtype; actual_count integer; actual_set text; bad_hash boolean;
begin
  select * into v from ops.scac_mutation_registry_version where registry_version='scac-mutation-registry.v101';
  if v.registry_version is null then return jsonb_build_object('registered',false,'reason','registry_unavailable'); end if;
  select count(*),'sha256:'||encode(public.digest(convert_to(coalesce(string_agg(entry_digest,',' order by ingress_key collate "C", entry_digest collate "C"),''),'UTF8'),'sha256'),'hex'),
         coalesce(bool_or(entry_digest is distinct from 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex')),false)
    into actual_count,actual_set,bad_hash from ops.scac_mutation_registry_entry where registry_version=v.registry_version;
  if actual_count<>v.entry_count or actual_set is distinct from v.entry_set_digest or bad_hash then
    return jsonb_build_object('registered',false,'reason','registry_corrupt','registry_version',v.registry_version,'registry_digest',v.registry_digest); end if;
  if p_expected_digest is distinct from v.registry_digest then return jsonb_build_object('registered',false,'reason','digest_mismatch','registry_version',v.registry_version,'registry_digest',v.registry_digest); end if;
  if p_ingress_key is null or p_ingress_key !~ '^[a-z][a-z0-9_-]+:' or p_ingress_key ~ E'[\n\r\t]' or char_length(p_ingress_key)>1000 then return jsonb_build_object('registered',false,'reason','malformed_ingress','registry_version',v.registry_version,'registry_digest',v.registry_digest); end if;
  select * into e from ops.scac_mutation_registry_entry where registry_version=v.registry_version and ingress_key=p_ingress_key;
  if e.ingress_key is null then return jsonb_build_object('registered',false,'reason','unknown_ingress','registry_version',v.registry_version,'registry_digest',v.registry_digest); end if;
  return jsonb_build_object('registered',true,'reason','registered_inventory','registry_version',v.registry_version,'registry_digest',v.registry_digest,
    'ingress_key',e.ingress_key,'ingress_kind',e.ingress_kind,'effect_class',e.effect_class,'entry_digest',e.entry_digest,
    'implementation_state',e.contract->>'implementation_state','atomic_database_mediation_operational',false);
end $fn$;
