-- Exact reviewed v37 source contracts, including the merged main ingress
-- changes and the current Progress directory implementation. Database ACL rows follow.
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v101',ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract
from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v100'
  and ingress_kind not in ('db_function_acl','db_relation_acl','db_column_acl');
update ops.scac_mutation_registry_entry set contract=$v101_runner${"ingress_key":"external-admin:tools/migrate.py","ingress_kind":"external_admin","operation":"tools/migrate.py","effect_class":"administrative_mutation","source_locator":"tools/migrate.py","schema_digest":"98449cb29a9273431e3a8220ed057dcdfb5ce21952a12112027fc6332298f22b","handler_digest":"98449cb29a9273431e3a8220ed057dcdfb5ce21952a12112027fc6332298f22b","write":true,"human_only":false,"authority_only":true,"principal_mode":"existing_script_specific_credential_boundary","mutation_kind":"scac.mutation.admin","target_surface":"scac.surface.runtime","delegates_to":[],"request_shape":"fixed_script_cli_contract","idempotency_mode":"script_specific_registered_current_control","rollback_class":"forward_fix_only","admission_class":"registered_inventory_only","owner_package":"11","implementation_state":"inventoried_not_atomically_mediated","classification_authorizing":false}$v101_runner$::jsonb,
  entry_digest='sha256:d5001f60bd669b9cc543c1cacbefe0fcded22685e78eb79d45e033f27ecf9a89'
where registry_version='scac-mutation-registry.v101' and ingress_key='external-admin:tools/migrate.py';

-- Exact database capability rows are projected from the just-built catalog.
-- The sealed expected category digests are independently recomputed by the DB gate.
with recursive connected(oid) as (
  select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union
  select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper
), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper
), functions as (
  select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,p.prosecdef,p.prokind,p.provolatile,p.proparallel,p.proconfig,p.proacl,p.proowner
    from pg_proc p join pg_namespace n on n.oid=p.pronamespace
   where n.nspname not in ('pg_catalog','information_schema') and p.prokind in ('f','p')
), capabilities as (
  select f.*,acl.grantee,acl.privilege_type,acl.is_grantable from functions f
  cross join lateral aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) acl
), observed as (
  select jsonb_build_object('ingress_key','db-function-acl:'||nspname||'.'||proname||'('||args||'):'||coalesce(r.rolname,'public')||':execute',
    'ingress_kind','db_function_acl','signature',nspname||'.'||proname||'('||args||')','security_definer',prosecdef,
    'function_kind',prokind,'volatility',provolatile,'parallel',proparallel,'config',coalesce(to_jsonb(proconfig),'[]'::jsonb),
    'grantee',coalesce(r.rolname,'public'),'privilege','execute','grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where prosecdef and privilege_type='EXECUTE' and grantee<>proowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',row->>'signature') contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v101',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper), capabilities as (
  select n.nspname,c.relname,c.relkind,c.relowner,acl.grantee,acl.privilege_type,acl.is_grantable
  from pg_class c join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) acl
  where n.nspname not in ('pg_catalog','information_schema') and c.relkind in ('r','p','v','m','f')
), observed as (
  select jsonb_build_object('ingress_key','db-relation-acl:'||nspname||'.'||relname||':'||coalesce(r.rolname,'public')||':'||lower(privilege_type),
    'ingress_kind','db_relation_acl','relation',nspname||'.'||relname,'relation_kind',relkind,'grantee',coalesce(r.rolname,'public'),
    'privilege',lower(privilege_type),'grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where privilege_type in ('INSERT','UPDATE','DELETE','TRUNCATE') and grantee<>relowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',row->>'relation') contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v101',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

with recursive connected(oid) as (select oid from pg_roles where rolname~'^carr_' and rolname<>'carr_ci' union select other.oid from connected c join pg_auth_members m on m.roleid=c.oid or m.member=c.oid join pg_roles other on other.oid=case when m.roleid=c.oid then m.member else m.roleid end where other.rolname<>'carr_ci' and not other.rolsuper), runtime_roles as (select r.oid,r.rolname from pg_roles r where r.oid in(select oid from connected) and not r.rolsuper), capabilities as (
  select n.nspname,c.relname,c.relkind,c.relowner,a.attname,acl.grantee,acl.privilege_type,acl.is_grantable
  from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace
  cross join lateral aclexplode(a.attacl) acl
  where a.attnum>0 and not a.attisdropped and a.attacl is not null and cardinality(a.attacl)>0
    and n.nspname not in ('pg_catalog','information_schema') and c.relkind in ('r','p','v','m','f')
), observed as (
  select jsonb_build_object('ingress_key','db-column-acl:'||nspname||'.'||relname||'.'||attname||':'||coalesce(r.rolname,'public')||':'||lower(privilege_type),
    'ingress_kind','db_column_acl','relation',nspname||'.'||relname,'relation_kind',relkind,'column',attname,
    'grantee',coalesce(r.rolname,'public'),'privilege',lower(privilege_type),'grantable',is_grantable) row
  from capabilities c left join pg_roles r on r.oid=c.grantee
  where privilege_type in ('INSERT','UPDATE') and grantee<>relowner and (grantee=0 or r.oid in(select oid from runtime_roles))
), contracts as (
  select row||jsonb_build_object('effect_class','administrative_mutation','owner_package','11','implementation_state','inventoried_not_atomically_mediated','classification_authorizing',false,'source_locator',(row->>'relation')||'.'||(row->>'column')) contract from observed
)
insert into ops.scac_mutation_registry_entry(registry_version,ingress_key,ingress_kind,effect_class,source_locator,entry_digest,contract)
select 'scac-mutation-registry.v101',contract->>'ingress_key',contract->>'ingress_kind',contract->>'effect_class',contract->>'source_locator',
  'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex'),contract from contracts;

do $$ declare actual_count integer; actual_digest text; expected jsonb; category text; kind text;
begin
  for category,kind in values ('secdef_execute','db_function_acl'),('relation_dml','db_relation_acl'),('column_dml','db_column_acl') loop
    select count(*),'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(coalesce(jsonb_agg(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator' order by ingress_key collate "C", ops.scac_canonical_json(contract-'effect_class'-'owner_package'-'implementation_state'-'classification_authorizing'-'source_locator') collate "C"),'[]'::jsonb)),'UTF8'),'sha256'),'hex')
      into actual_count,actual_digest from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v101' and ingress_kind=kind;
    select catalog_projection->category into expected from ops.scac_mutation_registry_version where registry_version='scac-mutation-registry.v101';
    if actual_count<>(expected->>'count')::integer or actual_digest<>expected->>'digest' then raise exception 'SCAC v37 database catalog category % drifted: count %, digest %',category,actual_count,actual_digest; end if;
  end loop;
end $$;

update ops.scac_mutation_registry_version v set entry_set_digest=(
  select 'sha256:'||encode(public.digest(convert_to(string_agg(e.entry_digest,',' order by e.ingress_key collate "C"),'UTF8'),'sha256'),'hex')
    from ops.scac_mutation_registry_entry e where e.registry_version=v.registry_version)
 where v.registry_version='scac-mutation-registry.v101';
do $definer_hardening_v101_seed$ declare v ops.scac_mutation_registry_version%rowtype; bad_hash boolean;
begin
  select * into strict v from ops.scac_mutation_registry_version where registry_version='scac-mutation-registry.v101';
  select coalesce(bool_or(entry_digest is distinct from 'sha256:'||encode(public.digest(convert_to(ops.scac_canonical_json(contract),'UTF8'),'sha256'),'hex')),false)
    into bad_hash from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v101';
  if (select count(*) from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v101')<>2516
    or (select count(*) from ops.scac_mutation_registry_entry where registry_version='scac-mutation-registry.v101' and ingress_kind not in ('db_function_acl','db_relation_acl','db_column_acl'))<>1008
    or bad_hash or v.registry_digest is distinct from 'sha256:818173acbf4c9316e3bca16448f58be26e8c34eb4f4546fa01e7f629c7f809c1'
    or v.entry_set_digest is distinct from 'sha256:7738a35265950f22719950177d418139f7ecfc205a3e2aff68b736e4e9969cc0' then
    raise exception 'Definer hardening v101 seed or entry-set seal drifted: actual % expected %', v.entry_set_digest, 'sha256:7738a35265950f22719950177d418139f7ecfc205a3e2aff68b736e4e9969cc0';
  end if;
end $definer_hardening_v101_seed$;

